/* Generated by design/build_essay_js.py - do not edit by hand. */
(function () {
  'use strict';
  if (window.__vgEssay) return;      /* one instance, ever */
  window.__vgEssay = true;

  var el = function (id) { return document.getElementById(id); };
  var editor = function () { return document.getElementById('vg-editor'); };

  /* ==================================================================== 1
     READ ALOUD

     Uses the speech synthesiser built into the browser, so there is no
     network call and the essay never leaves the machine — which matters, this
     being the most personal thing the app holds.
  ==================================================================== */
  /* Four separate things were stopping this from making any sound.

     One: the whole essay went in as a single utterance. Chrome quietly gives
     up on long ones and cuts off after about fifteen seconds anyway, so an
     essay — which is the only thing anybody would press this on — was exactly
     the case that failed. It is now read a sentence at a time.

     Two: cancel() and speak() were called in the same tick. Chrome swallows
     the speak when you do that. Now nothing is cancelled unless something is
     actually talking, and the restart waits a beat.

     Three: the voice list is empty until the browser has loaded it, which on
     a first visit happens after this code runs. It is warmed up below and
     re-read when the browser says it has changed.

     Four: when it failed it failed silently. The button said "Stop" and no
     sound came out, and there was no way to tell whether the app was broken
     or the machine had no voices. It now says so. */

  var speaking = false;
  var queue = [], qi = 0, resumeTimer = null, startCheck = null;
  var voice = null, voicesReady = false;

  function loadVoices() {
    if (!window.speechSynthesis) return;
    var list = [];
    try { list = window.speechSynthesis.getVoices() || []; } catch (e) { return; }
    if (!list.length) return;
    voicesReady = true;
    /* Prefer a local English voice: the network ones stall on a bad
       connection, and a mismatched language reads an essay as gibberish. */
    var best = null, i, v;
    for (i = 0; i < list.length; i++) {
      v = list[i];
      if (!/^en/i.test(v.lang || '')) continue;
      if (!best) best = v;
      if (v.localService) { best = v; break; }
    }
    voice = best || list[0] || null;
  }

  if (window.speechSynthesis) {
    loadVoices();
    /* Fires once the list is really available. */
    window.speechSynthesis.onvoiceschanged = loadVoices;
    setTimeout(loadVoices, 250);
    setTimeout(loadVoices, 1200);
  }

  function readNote(msg) {
    var b = el('vg-read');
    if (!b) return;
    b.setAttribute('title', msg);
    var bar = b.parentNode;
    if (!bar) return;
    var note = el('vg-read-note');
    if (!note) {
      note = document.createElement('span');
      note.id = 'vg-read-note';
      note.className = 'faint tiny';
      bar.appendChild(note);
    }
    note.textContent = msg;
    clearTimeout(note.__t);
    note.__t = setTimeout(function () { if (note) note.textContent = ''; }, 6000);
  }

  function setReadLabel(on) {
    var b = el('vg-read');
    if (!b) return;
    var span = b.querySelector('.lbl') || b;
    var want = on ? '■ Stop' : '🔊 Read aloud';
    if (span.textContent !== want) span.textContent = want;
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  }

  function clearTimers() {
    if (resumeTimer) { clearInterval(resumeTimer); resumeTimer = null; }
    if (startCheck) { clearTimeout(startCheck); startCheck = null; }
  }

  function stopSpeech() {
    clearTimers();
    queue = []; qi = 0;
    speaking = false;
    if (window.speechSynthesis) {
      try { window.speechSynthesis.cancel(); } catch (e) {}
    }
    setReadLabel(false);
  }

  /* Split on sentence ends, then break anything still too long on a comma or
     a space. Short pieces are what keep Chrome from cutting out, and they also
     make the pauses fall where a reader would put them. */
  function chunk(text) {
    var parts = String(text).replace(/\s+/g, ' ').trim()
                  .match(/[^.!?]+[.!?]*\s*/g) || [];
    var out = [], i, p;
    for (i = 0; i < parts.length; i++) {
      p = parts[i].trim();
      if (!p) continue;
      while (p.length > 180) {
        var cut = p.lastIndexOf(',', 180);
        if (cut < 60) cut = p.lastIndexOf(' ', 180);
        if (cut < 60) cut = 180;
        out.push(p.slice(0, cut).trim());
        p = p.slice(cut).trim();
      }
      if (p) out.push(p);
    }
    return out;
  }

  function speakNext() {
    if (!speaking) return;
    if (qi >= queue.length) { stopSpeech(); return; }
    var u = new SpeechSynthesisUtterance(queue[qi++]);
    u.rate = 0.95;            /* just under natural pace: clumsy sentences
                                 stand out more when they are not rushed */
    u.pitch = 1;
    u.volume = 1;
    if (voice) { u.voice = voice; u.lang = voice.lang; }
    else u.lang = 'en-US';
    u.onend = function () { if (speaking) speakNext(); };
    u.onerror = function (e) {
      /* An error raised because we cancelled is not a failure. */
      if (!speaking || (e && e.error === 'interrupted') || (e && e.error === 'canceled')) return;
      stopSpeech();
      readNote('Your browser stopped the reading. Try again, or check that sound is on.');
    };
    try { window.speechSynthesis.speak(u); }
    catch (err) { stopSpeech(); readNote('This browser could not read the draft aloud.'); }
  }

  function beginSpeech(pieces) {
    queue = pieces; qi = 0;
    speaking = true;
    setReadLabel(true);
    speakNext();

    /* Chrome pauses its own synthesiser after a while. Nudging it is the
       accepted fix, and it is harmless when nothing is speaking. */
    clearTimers();
    resumeTimer = setInterval(function () {
      if (!speaking) { clearTimers(); return; }
      try {
        if (window.speechSynthesis.paused) window.speechSynthesis.resume();
      } catch (e) {}
    }, 5000);

    /* If no sound has begun by now, say so rather than sitting there looking
       like it is working. */
    startCheck = setTimeout(function () {
      if (!speaking) return;
      var ss = window.speechSynthesis;
      if (!ss.speaking && !ss.pending) {
        stopSpeech();
        readNote(voicesReady
          ? 'No sound came out — check the volume and that this tab is not muted.'
          : 'This device has no speech voices installed, so it cannot read aloud.');
      }
    }, 1800);
  }

  function readAloud() {
    var box = editor();
    if (!box) return;
    if (!window.speechSynthesis || typeof SpeechSynthesisUtterance === 'undefined') {
      readNote('This browser cannot read text aloud. Chrome, Edge and Safari can.');
      return;
    }
    if (speaking) { stopSpeech(); return; }

    /* Read the selection if there is one — being able to check a single
       awkward paragraph is more useful than only ever hearing the whole
       thing. */
    var text = '';
    if (box.selectionStart !== box.selectionEnd) {
      text = box.value.substring(box.selectionStart, box.selectionEnd);
    }
    if (!text.trim()) text = box.value;
    if (!text.trim()) { readNote('There is nothing written yet.'); return; }

    if (!voicesReady) loadVoices();
    var pieces = chunk(text);
    if (!pieces.length) return;

    /* Speaking straight out of the click keeps the browser's "the user asked
       for this" permission intact. Only when something is already talking do
       we cancel, and then the restart waits a beat, because cancelling and
       speaking in the same tick is what silences Chrome. */
    var ss = window.speechSynthesis;
    if (ss.speaking || ss.pending) {
      try { ss.cancel(); } catch (e) {}
      setTimeout(function () { beginSpeech(pieces); }, 140);
      speaking = true;
      setReadLabel(true);
    } else {
      beginSpeech(pieces);
    }
  }

  /* ==================================================================== 2
     FOCUS MODE

     Dims everything that is not the words. The score, the problem list and the
     chips are useful when editing and actively harmful when drafting — you
     cannot write a first draft while something counts your mistakes.
  ==================================================================== */
  function toggleFocus(force) {
    var root = document.querySelector('.vg-app');
    if (!root) return;
    var on = force === undefined ? !root.hasAttribute('data-focus') : force;
    if (on) root.setAttribute('data-focus', '1');
    else root.removeAttribute('data-focus');
    var b = el('vg-focus');
    if (b) {
      var span = b.querySelector('.lbl') || b;
      var want = on ? '◱ Exit focus' : '◱ Focus';
      if (span.textContent !== want) span.textContent = want;
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    }
    if (on) { var e = editor(); if (e) e.focus(); }
  }

  /* ==================================================================== 3
     SPRINT

     A countdown with one rule: no editing, no deleting, just get words down.
     Perfectionism is what stops people finishing a first draft, and a running
     clock is the cheapest known cure.
  ==================================================================== */
  var sprint = { end: 0, timer: null, startWords: 0 };

  function wordCount() {
    var box = editor();
    if (!box) return 0;
    var m = box.value.match(/[A-Za-z][A-Za-z'’\-]*/g);
    return m ? m.length : 0;
  }

  function paintSprint() {
    var wrap = el('vg-sprint');
    if (!wrap) return;
    if (!sprint.end) {
      wrap.hidden = true;
      return;
    }
    wrap.hidden = false;
    var left = Math.max(0, Math.round((sprint.end - Date.now()) / 1000));
    var mm = Math.floor(left / 60), ss = left % 60;
    var t = el('vg-sprint-time');
    var want = mm + ':' + (ss < 10 ? '0' : '') + ss;
    if (t && t.textContent !== want) t.textContent = want;

    var gained = Math.max(0, wordCount() - sprint.startWords);
    var g = el('vg-sprint-words');
    var wantW = gained + (gained === 1 ? ' word' : ' words');
    if (g && g.textContent !== wantW) g.textContent = wantW;

    if (left <= 0) endSprint(true);
  }

  function startSprint(minutes) {
    sprint.end = Date.now() + minutes * 60000;
    sprint.startWords = wordCount();
    if (sprint.timer) clearInterval(sprint.timer);
    sprint.timer = setInterval(paintSprint, 250);
    paintSprint();
    var e = editor();
    if (e) e.focus();
  }

  function endSprint(finished) {
    if (sprint.timer) clearInterval(sprint.timer);
    sprint.timer = null;
    var gained = Math.max(0, wordCount() - sprint.startWords);
    sprint.end = 0;
    var wrap = el('vg-sprint');
    if (wrap) {
      if (finished) {
        wrap.hidden = false;
        var t = el('vg-sprint-time');
        if (t) t.textContent = 'Done';
        var g = el('vg-sprint-words');
        if (g) g.textContent = gained + (gained === 1 ? ' word' : ' words') + ' written';
        setTimeout(function () { if (!sprint.end && wrap) wrap.hidden = true; }, 8000);
      } else {
        wrap.hidden = true;
      }
    }
    /* Saving is the server's job, so ask it the same way a person would. */
    var save = document.getElementById('vg-save');
    if (save) save.click();
  }

  /* ==================================================================== 5
     WIRING — one delegated listener, so React can re-render freely.
  ==================================================================== */
  document.addEventListener('click', function (e) {
    var t = e.target;
    if (!t || !t.closest) return;

    if (t.closest('#vg-read')) { readAloud(); return; }
    if (t.closest('#vg-focus')) { toggleFocus(); return; }
    if (t.closest('#vg-sprint-stop')) { endSprint(false); return; }

    var s = t.closest('[data-sprint]');
    if (s) { startSprint(parseInt(s.getAttribute('data-sprint'), 10) || 10); return; }

  }, false);

  document.addEventListener('keydown', function (e) {
    var box = editor();
    var inEditor = box && document.activeElement === box;

    /* Ctrl/Cmd+S — the reflex everyone has. Without this it opens the
       browser's save-page dialogue, which is startling and useless. */
    if ((e.ctrlKey || e.metaKey) && (e.key === 's' || e.key === 'S')) {
      e.preventDefault();
      var save = document.getElementById('vg-save');
      if (save) save.click();
      return;
    }
    /* Escape leaves focus mode and stops the reading. */
    if (e.key === 'Escape') {
      if (speaking) stopSpeech();
      toggleFocus(false);
      return;
    }
    /* Ctrl/Cmd+Enter reads the draft aloud. */
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && inEditor) {
      e.preventDefault();
      readAloud();
    }
  }, false);

  /* Leaving the page mid-sentence should not leave a voice talking. */
  window.addEventListener('beforeunload', function () {
    if (window.speechSynthesis) window.speechSynthesis.cancel();
  });

  /* Cheap poll to keep the labels honest after a re-render, and to notice when
     we have navigated away from the editor. */
  setInterval(function () {
    if (!editor()) {
      if (speaking) stopSpeech();
      if (sprint.end) endSprint(false);
      return;
    }
    if (!speaking) setReadLabel(false);
  }, 500);
})();
